"""Русские уроки, словарь и пояснения к метрикам линейной лаборатории.

Контент возвращается каталогом API. Пресеты используют публичные идентификаторы
реестров данных и моделей, а формулы читаются без отдельного рендера LaTeX.
"""

from __future__ import annotations

from typing import Any


def _preset(
    model: str,
    *,
    name: str = "linear",
    data: dict[str, Any] | None = None,
    params: dict[str, Any] | None = None,
    epochs: int = 100,
) -> dict[str, Any]:
    dataset_params: dict[str, Any] = {
        "n_samples": 180,
        "n_features": 2,
        "noise": 8,
        "correlation": 0.2,
        "outliers": 0,
        "seed": 42,
    }
    dataset_params.update(data or {})
    return {
        "dataset": {"kind": "synthetic", "name": name, "params": dataset_params},
        "model": model,
        "params": dict(params or {}),
        "epochs": epochs,
    }


