GLOSSARY: list[dict[str, str]] = [
    {"term": "Наблюдение · sample", "definition": "Одна строка данных: один объект или одно измерение. Число строк n и число признаков p — разные размеры таблицы."},
    {"term": "Матрица признаков · design matrix", "definition": "Таблица числовых входов X размером n строк на p столбцов. Для совместного расчета свободного члена к ней можно добавить столбец единиц."},
    {"term": "Вектор · vector", "definition": "Упорядоченный набор чисел. Вектор w содержит коэффициенты, а вектор y содержит цели для всех наблюдений. Порядок чисел должен совпадать с соответствующими столбцами или строками."},
    {"term": "Транспонирование · transpose", "definition": "Перестановка строк и столбцов матрицы. Знак ᵀ обозначает эту операцию: элемент строки i и столбца j становится элементом строки j и столбца i."},
    {"term": "Норма · norm", "definition": "Способ измерить размер вектора. Для (3, −4) L₁ = 7, L₂ = 5, а квадрат L₂ = 25. Нормы и их квадраты дают разные штрафы."},
    {"term": "Ранг · rank", "definition": "Число независимых направлений столбцов или строк матрицы. Повторение одного столбца не добавляет независимое направление. Полный столбцовый ранг нужен для обычной обратной формулы МНК."},
    {"term": "Псевдообратная матрица · pseudoinverse", "definition": "Обобщение обратной матрицы для прямоугольных и вырожденных задач. Позволяет получить решение МНК; при нескольких решениях выбирает решение минимальной евклидовой нормы."},
    {"term": "Среднее · mean", "definition": "Сумма чисел, деленная на их количество. Для 1, 2, 12 среднее равно 5. Большое крайнее значение способно заметно изменить среднее."},
    {"term": "Медиана · median", "definition": "Середина отсортированных чисел. Для 1, 2, 12 медиана равна 2. При четном количестве обычно берется среднее двух центральных чисел."},
    {"term": "Стандартное отклонение · standard deviation", "definition": "Корень из дисперсии, меры разброса относительно среднего. Имеет единицы исходной величины. В стандартизации используется обучающий масштаб конкретного столбца."},
    {"term": "Гиперпараметр · hyperparameter", "definition": "Настройка процедуры, выбираемая перед обучением: alpha, степень полинома, число эпох. Коэффициенты w и b, получаемые из обучения, называются параметрами модели."},
    {"term": "Базовое сравнение · baseline", "definition": "Простая явно заданная модель для сравнения качества. Например, прогноз среднего обучающего y. Среднее в формуле R² берется по оцениваемой части, поэтому эти два сравнения могут различаться."},
    {"term": "Признак · feature", "definition": "Входное значение, известное к моменту предсказания. Столбец X может быть исходным измерением или результатом преобразования."},
    {"term": "Целевая переменная · target", "definition": "Величина y, которую требуется предсказать. Для регрессии она числовая и имеет содержательный смысл; номер класса сам по себе таким смыслом не обладает."},
    {"term": "Предсказание · prediction", "definition": "Число ŷ = model(X). Настоящее y и предсказание ŷ используются для оценки ошибок."},
    {"term": "Коэффициент · coefficient", "definition": "Множитель признака в линейном предикторе. Его размерность и смысл зависят от преобразований и единиц признака."},
    {"term": "Свободный член · intercept", "definition": "Постоянное слагаемое b. Это предсказание при нулевом векторе используемых признаков. В центрированном пространстве ноль соответствует средним обучающим значениям."},
    {"term": "Остаток · residual", "definition": "Разность e = y − ŷ. Положительный остаток означает недооценку, отрицательный — переоценку. Отдельные алгоритмы обозначают ошибку обратным знаком."},
    {"term": "Функция потерь · loss", "definition": "Правило цены ошибки. Квадрат, модуль и квантильная потеря наказывают разные виды промахов по-разному."},
    {"term": "Полная функция · objective", "definition": "Число, которое минимизирует алгоритм: функция потерь в выбранной нормировке плюс штрафы. Для байесовских процедур критерий может быть другим."},
    {"term": "Регуляризация · regularization", "definition": "Дополнительное предпочтение или ограничение решения. Например, L₂ предпочитает небольшие коэффициенты, а групповой штраф учитывает группы."},
    {"term": "Штраф · penalty", "definition": "Добавка к функции оптимизации. Большой штраф делает соответствующее свойство решения дорогим. Он не входит автоматически в метрику новых предсказаний."},
    {"term": "alpha", "definition": "Обычно сила штрафа, но ее точный смысл зависит от модели. У Ridge и Lasso разная нормировка ошибки, а у BayesianRidge alpha относится к точности шума."},
    {"term": "L₁", "definition": "Сумма модулей коэффициентов Σ|wⱼ|. Часто создает точные нули в решении регуляризованной регрессии."},
    {"term": "L₂", "definition": "Евклидова норма sqrt(Σwⱼ²). В Ridge используется квадрат этой нормы, Σwⱼ²."},
    {"term": "L₀", "definition": "Количество ненулевых коэффициентов. Обозначение историческое: эта величина не является нормой в строгом смысле."},
    {"term": "Разреженность · sparsity", "definition": "Большое число точных нулей в коэффициентах или матрице данных. Разреженные коэффициенты и разреженный формат хранения X — отдельные свойства."},
    {"term": "Мультиколлинеарность · multicollinearity", "definition": "Точная или близкая линейная зависимость столбцов X. Коэффициенты могут стать нестабильными даже при небольших ошибках предсказания."},
    {"term": "Стандартизация · standardization", "definition": "Вычитание обучающего среднего и деление на обучающий масштаб. Применение StandardScaler не делает произвольное распределение нормальным."},
    {"term": "Градиент · gradient", "definition": "Вектор скоростей изменения функции по ее параметрам. Небольшой шаг против градиента часто уменьшает функцию, если размер шага выбран подходяще."},
    {"term": "Скорость обучения · learning rate", "definition": "Число eta, определяющее размер обновления. Большое значение может привести к расходимости, маленькое — к медленному обучению."},
    {"term": "Эпоха · epoch", "definition": "Один проход по обучающим наблюдениям. Итерация решателя может означать другое; проверяй подпись фактической истории."},
    {"term": "Сходимость · convergence", "definition": "Достижение критерия остановки численного алгоритма. Она описывает решение задачи оптимизации и сама по себе не гарантирует хороших новых предсказаний."},
    {"term": "tol", "definition": "Численная точность критерия остановки. В разных решателях этот критерий различается. Это не порог допустимой предметной ошибки прогноза."},
    {"term": "Путь регуляризации · regularization path", "definition": "Решения нескольких задач при разных силах штрафа на одних обучающих данных. Это отдельная последовательность от эпох при фиксированном штрафе."},
    {"term": "Активный набор · active set", "definition": "Признаки или ограничения, с которыми работает текущий этап алгоритма. Lars и OMP формируют наборы по своим правилам."},
    {"term": "Выпуклость · convexity", "definition": "Свойство задачи, при котором локальный минимум является глобальным. Оно не гарантирует единственности решения и не устраняет численные ограничения."},
    {"term": "Локальный минимум · local minimum", "definition": "Решение лучше соседних решений, но может уступать удаленному. Для невыпуклых задач старт и решатель могут влиять на итог."},
    {"term": "Выброс · outlier", "definition": "Наблюдение, необычное относительно выбранного описания данных. Это может быть реальным редким событием, ошибкой или следствием неверной модели."},
    {"term": "Устойчивость · robustness", "definition": "Слабая чувствительность оценки к определенному виду загрязнения данных. Устойчивость к большим остаткам и к экстремальным признакам может различаться."},
    {"term": "Гетероскедастичность · heteroscedasticity", "definition": "Изменение разброса ошибок при разных значениях признаков. Видна, например, как расширение облака остатков."},
    {"term": "Обучение · train", "definition": "Часть наблюдений, используемая для подгонки коэффициентов и параметров преобразований."},
    {"term": "Проверка · validation", "definition": "Часть наблюдений для сравнения вариантов модели и выбора настроек. После многократного выбора она уже участвует в разработке решения."},
    {"term": "Итоговый тест · test", "definition": "Отложенные данные для оценки уже выбранной модели. Если менять настройки по их результатам, они становятся частью подбора."},
    {"term": "Перекрестная проверка · cross-validation", "definition": "Несколько внутренних разбиений для оценки качества и его изменчивости. Преобразования обучаются внутри каждого обучающего сгиба."},
    {"term": "Утечка данных · data leakage", "definition": "Использование во время обучения или выбора сведений, недоступных при реальном предсказании. Примеры: масштабирование по всем строкам или признак, содержащий будущий результат."},
    {"term": "Случайное зерно · random seed", "definition": "Число, задающее воспроизводимую последовательность псевдослучайных действий. Оно фиксирует опыт, но не доказывает устойчивость результата на других выборках."},
    {"term": "Полиномиальные признаки · polynomial features", "definition": "Дополнительные столбцы x², x₁x₂ и другие степени и произведения. Предсказание может быть кривой, оставаясь линейным по коэффициентам."},
    {"term": "Априорное распределение · prior", "definition": "Вероятностное предположение о параметрах до учета текущих наблюдений."},
    {"term": "Апостериорное распределение · posterior", "definition": "Распределение параметров после обновления априорного предположения данными в выбранной вероятностной модели."},
    {"term": "Точность распределения · precision", "definition": "В байесовских формулах это обратная дисперсия, 1/variance. Ее не следует путать с метрикой precision классификации."},
    {"term": "Квантиль · quantile", "definition": "Граница распределения для заданной доли q. q = 0.5 задает медиану; в регрессии оценивается условный квантиль при заданных признаках."},
    {"term": "Функция связи · link function", "definition": "В GLM связывает условное среднее с линейным предиктором. При log-связи log(mu) = b + Xw, а mu = exp(b + Xw)."},
    {"term": "Девианса · deviance", "definition": "Мера несоответствия прогнозов наблюдениям относительно выбранного распределения. Для разных распределений используются разные формулы и области допустимых значений."},
    {"term": "Срез · slice", "definition": "Изображение зависимости от нескольких переменных при зафиксированных остальных. Показывает часть полной многомерной функции."},
    {"term": "Экстраполяция · extrapolation", "definition": "Предсказание за пределами области обучающих признаков. Хорошее качество внутри наблюдавшейся области не гарантирует качество далеко за ее пределами."},
]


